<body>
<div class="wrap">
  <header>
    <h1><em>BLIND</em> EXPLORERS</h1>
    <p class="sub">A 23×23 perfect maze. 24 bots start with empty memories — they feel walls one
    cell at a time, wander depth-first, mark exhausted branches as dead and backtrack, never
    re-walking a corridor more than twice. Neither the layout nor the exit is known in advance.
    The timer freezes the moment the last bot makes it home.</p>
  </header>

  <div class="stats">
    <div class="stat">
      <span class="label">Elapsed</span>
      <span class="value amber" id="timer">T+00000</span>
      <span class="mini" id="timerSub">0.0 s @ 70 ticks/s</span>
    </div>
    <div class="stat" id="statCompleted">
      <span class="label">Home</span>
      <span class="value" id="completed">0 / 24</span>
      <span class="mini">bots at the exit</span>
    </div>
    <div class="stat">
      <span class="label">Status</span>
      <span class="value sm" id="status">EXPLORING…</span>
      <span class="mini" id="seed">SEED —</span>
    </div>
  </div>

  <div id="maze"><canvas id="cv" width="718" height="718"></canvas></div>

  <div class="controls">
    <button id="reset">Reset</button>
    <button id="pause">Pause</button>
    <label class="speed">Speed
      <input id="speed" type="range" min="10" max="240" value="70">
      <span id="speedVal">70 t/s</span>
    </label>
  </div>

  <footer>
    <span class="sw sp"></span>spawn
    <span class="sw ex"></span>exit
    <span class="sw th"></span>bot trail — brighter where a corridor was walked twice
    &nbsp;·&nbsp;<kbd>space</kbd> pause
    &nbsp;·&nbsp;<code>game.reset(1234)</code> replays a seed exactly
  </footer>
</div>

<script>
(()=>{
'use strict';
const $=s=>document.querySelector(s);

/* ---------------- seeded RNG ---------------- */
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^(a>>>15),1|a);t=t+Math.imul(t^(t>>>7),61|t)^t;return((t^(t>>>14))>>>0)/4294967296;};}

/* ---------------- constants ---------------- */
const ROWS=23,COLS=23,CELL=30,PAD=14,NBOTS=24;
const W=COLS*CELL+PAD*2,H=ROWS*CELL+PAD*2;
const DS=['n','e','s','w'];
const DV={n:[-1,0],e:[0,1],s:[1,0],w:[0,-1]};
const OPP={n:'s',s:'n',e:'w',w:'e'};
const K=(r,c)=>r+'_'+c;
const inB=(r,c)=>r>=0&&r<ROWS&&c>=0&&c<COLS;
const cx=c=>PAD+c*CELL+CELL/2;
const cy=r=>PAD+r*CELL+CELL/2;

/* ---------------- canvases ---------------- */
const cv=$('#cv'),ctx=cv.getContext('2d');
const dpr=Math.min(window.devicePixelRatio||1,2);
cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);
function layer(){
  const c=document.createElement('canvas');
  c.width=W*dpr;c.height=H*dpr;
  const g=c.getContext('2d');g.setTransform(dpr,0,0,dpr,0,0);
  return[c,g];
}
const[baseCv,bctx]=layer();   /* static maze */
const[trailCv,tctx]=layer();  /* accumulated exploration threads */

/* ---------------- dom refs ---------------- */
const timerEl=$('#timer'),timerSub=$('#timerSub'),completedEl=$('#completed'),
      statusEl=$('#status'),seedEl=$('#seed'),statDone=$('#statCompleted'),
      pauseBtn=$('#pause'),speedInput=$('#speed'),speedVal=$('#speedVal');

/* ---------------- state ---------------- */
let seed=0,rand=Math.random;
let grid=[],spawn={r:0,c:0},exitC={r:0,c:0};
let bots=[],tickCount=0,allDone=false;
let tps=70,tickMs=1000/70,running=true,acc=0,lastFrame=performance.now();
let fx=[],fxSeen=new Set(),flashAt=-1,flashDone=false,lastDone=-1;

/* ---------------- maze generation (generator-side only) ---------------- */
function genMaze(sr,sc){
  grid=Array.from({length:ROWS},()=>Array.from({length:COLS},()=>({n:true,e:true,s:true,w:true})));
  const seen=Array.from({length:ROWS},()=>Array(COLS).fill(false));
  const st=[[sr,sc]];seen[sr][sc]=true;
  while(st.length){
    const[r,c]=st[st.length-1];const opts=[];
    for(const d of DS){
      const nr=r+DV[d][0],nc=c+DV[d][1];
      if(inB(nr,nc)&&!seen[nr][nc])opts.push(d);
    }
    if(!opts.length){st.pop();continue;}
    const d=opts[(rand()*opts.length)|0];
    const nr=r+DV[d][0],nc=c+DV[d][1];
    grid[r][c][d]=false;grid[nr][nc][OPP[d]]=false;
    seen[nr][nc]=true;st.push([nr,nc]);
  }
}
/* farthest cell from spawn becomes the exit (placement only — bots never see this) */
function farthest(fr,fc){
  const dist=Array.from({length:ROWS},()=>Array(COLS).fill(-1));
  dist[fr][fc]=0;const q=[[fr,fc]];let best={r:fr,c:fc},bd=0;
  for(let i=0;i<q.length;i++){
    const[r,c]=q[i];
    for(const d of DS){
      if(grid[r][c][d])continue;
      const nr=r+DV[d][0],nc=c+DV[d][1];
      if(dist[nr][nc]<0){
        dist[nr][nc]=dist[r][c]+1;
        if(dist[nr][nc]>bd){bd=dist[nr][nc];best={r:nr,c:nc};}
        q.push([nr,nc]);
      }
    }
  }
  return best;
}

/* ---------------- bots: local-knowledge DFS (Tremaux-style) ----------------
   Each bot only senses the walls of the cell it currently occupies, remembers
   which cells it has visited, keeps a backtrack stack, and marks a cell dead
   when it abandons it with no unexplored passages left. Forward moves only
   enter unvisited cells; retreats only pop the stack — so no passage is ever
   traversed more than twice by the same bot. */
function makeBot(i,brng){
  const order=DS.slice();               /* seeded direction preference */
  for(let k=3;k>0;k--){const j=(brng()*(k+1))|0;const t=order[k];order[k]=order[j];order[j]=t;}
  return{
    id:i,
    color:'hsl('+(((i*137.508)%360).toFixed(1))+' 85% 62%)',
    rng:brng,order,
    pos:{r:spawn.r,c:spawn.c},prev:{r:spawn.r,c:spawn.c},
    path:[{r:spawn.r,c:spawn.c}],
    visited:new Set([K(spawn.r,spawn.c)]),
    memory:{},                          /* walls learned so far, cell by cell */
    stack:[],deadEnds:[],finishTick:null
  };
}
function learn(b,r,c){
  const w=grid[r][c];
  b.memory[K(r,c)]={n:w.n,e:w.e,s:w.s,w:w.w};
}
function moveBot(b,nr,nc){
  b.prev={r:b.pos.r,c:b.pos.c};
  b.pos={r:nr,c:nc};
  b.path.push({r:nr,c:nc});
  b.visited.add(K(nr,nc));
  learn(b,nr,nc);
  tctx.globalAlpha=.13;tctx.strokeStyle=b.color;tctx.lineWidth=3;tctx.lineCap='round';
  tctx.beginPath();tctx.moveTo(cx(b.prev.c),cy(b.prev.r));tctx.lineTo(cx(nc),cy(nr));tctx.stroke();
  tctx.globalAlpha=1;
  if(nr===exitC.r&&nc===exitC.c)b.finishTick=tickCount;   /* discovered on arrival */
}
function stepBot(b){
  if(b.finishTick!=null)return;
  const w=grid[b.pos.r][b.pos.c];       /* sense walls of the current cell only */
  const opts=[];
  for(const d of b.order){
    if(w[d])continue;
    const nr=b.pos.r+DV[d][0],nc=b.pos.c+DV[d][1];
    if(!b.visited.has(K(nr,nc)))opts.push([nr,nc]);
  }
  if(opts.length){
    let pick=opts[0];                   /* prefer the bot's seeded direction order */
    if(opts.length>1&&b.rng()<0.3)pick=opts[(b.rng()*opts.length)|0];
    b.stack.push({r:b.pos.r,c:b.pos.c});
    moveBot(b,pick[0],pick[1]);
  }else{
    /* dead end or fully explored branch: record it as dead, backtrack */
    b.deadEnds.push({r:b.pos.r,c:b.pos.c});
    if(!b.stack.length)return;
    const p=b.stack.pop();
    moveBot(b,p.r,p.c);
  }
}
function stepOnce(){
  if(allDone)return;
  tickCount++;
  for(let i=0;i<bots.length;i++)stepBot(bots[i]);
  if(!allDone){
    allDone=true;
    for(let i=0;i<bots.length;i++)if(bots[i].finishTick==null){allDone=false;break;}
  }
}

/* ---------------- public scripting API ---------------- */
const game={
  tick(n){
    n=Math.floor(+n||0);
    for(let i=0;i<n&&!allDone;i++)stepOnce();
  },
  reset(s){
    let sd;
    if(typeof s==='number'&&Number.isFinite(s))sd=s>>>0;
    else if(typeof s==='string'&&s.trim()!==''&&Number.isFinite(+s))sd=(+s)>>>0;
    else sd=(Math.random()*4294967296)>>>0;
    init(sd);
  },
  get elapsed(){return tickCount;},          /* frozen once every bot is home */
  get size(){return{rows:ROWS,cols:COLS};},
  get spawn(){return{r:spawn.r,c:spawn.c};},
  get exit(){return{r:exitC.r,c:exitC.c};},
  walls(r,c){
    if(!inB(r,c))return{n:true,e:true,s:true,w:true};
    const w=grid[r][c];return{n:w.n,e:w.e,s:w.s,w:w.w};
  },
  get bots(){return bots;},
  get seed(){return seed;},
  get finished(){return allDone;}
};
window.game=game;

/* ---------------- init / reset ---------------- */
function init(sd){
  seed=sd>>>0;rand=mulberry32(seed);
  const sr=(rand()*ROWS)|0,sc=(rand()*COLS)|0;
  genMaze(sr,sc);
  spawn={r:sr,c:sc};
  const f=farthest(sr,sc);exitC={r:f.r,c:f.c};
  bots=[];
  for(let i=0;i<NBOTS;i++){
    const b=makeBot(i,mulberry32((rand()*4294967296)>>>0));
    learn(b,sr,sc);
    bots.push(b);
  }
  tickCount=0;allDone=false;acc=0;
  fx=[];fxSeen=new Set();flashAt=-1;flashDone=false;lastDone=-1;
  tctx.clearRect(0,0,W,H);
  renderBase();
}

/* ---------------- static layer ---------------- */
function renderBase(){
  bctx.clearRect(0,0,W,H);
  bctx.fillStyle='#0c1016';bctx.fillRect(0,0,W,H);
  bctx.fillStyle='#141b25';
  for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++)
    bctx.fillRect(PAD+c*CELL,PAD+r*CELL,CELL,CELL);
  bctx.fillStyle='rgba(98,231,155,.09)';
  bctx.fillRect(PAD+exitC.c*CELL,PAD+exitC.r*CELL,CELL,CELL);
  bctx.fillStyle='rgba(108,201,255,.07)';
  bctx.fillRect(PAD+spawn.c*CELL,PAD+spawn.r*CELL,CELL,CELL);
  bctx.strokeStyle='#8ea6c8';bctx.lineWidth=2;bctx.lineCap='round';bctx.lineJoin='round';
  bctx.beginPath();
  for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++){
    const x=PAD+c*CELL,y=PAD+r*CELL,w=grid[r][c];
    if(w.n){bctx.moveTo(x,y);bctx.lineTo(x+CELL,y);}
    if(w.w){bctx.moveTo(x,y);bctx.lineTo(x,y+CELL);}
    if(r===ROWS-1&&w.s){bctx.moveTo(x,y+CELL);bctx.lineTo(x+CELL,y+CELL);}
    if(c===COLS-1&&w.e){bctx.moveTo(x+CELL,y);bctx.lineTo(x+CELL,y+CELL);}
  }
  bctx.stroke();
  bctx.strokeStyle='rgba(108,201,255,.7)';bctx.lineWidth=1.5;
  bctx.strokeRect(PAD+spawn.c*CELL+7.5,PAD+spawn.r*CELL+7.5,CELL-15,CELL-15);
  const ex=cx(exitC.c),ey=cy(exitC.r);
  bctx.strokeStyle='rgba(98,231,155,.9)';bctx.lineWidth=2;
  bctx.beginPath();bctx.arc(ex,ey,9,0,Math.PI*2);bctx.stroke();
  bctx.save();bctx.translate(ex,ey);bctx.rotate(Math.PI/4);
  bctx.fillStyle='rgba(98,231,155,.95)';bctx.fillRect(-3.2,-3.2,6.4,6.4);
  bctx.restore();
}

/* ---------------- dynamic draw ---------------- */
function draw(now){
  ctx.clearRect(0,0,W,H);
  ctx.drawImage(baseCv,0,0,W,H);
  ctx.drawImage(trailCv,0,0,W,H);
  const ph=(now/1400)%1;
  ctx.strokeStyle='rgba(98,231,155,'+(0.45*(1-ph)).toFixed(3)+')';
  ctx.lineWidth=2;
  ctx.beginPath();ctx.arc(cx(exitC.c),cy(exitC.r),5+ph*16,0,Math.PI*2);ctx.stroke();
  for(let i=fx.length-1;i>=0;i--){
    const f=fx[i],k=(now-f.start)/750;
    if(k>=1){fx.splice(i,1);continue;}
    ctx.strokeStyle='rgba(255,255,255,'+(0.55*(1-k)).toFixed(3)+')';
    ctx.lineWidth=2;
    ctx.beginPath();ctx.arc(f.x,f.y,4+k*(f.big?36:20),0,Math.PI*2);ctx.stroke();
  }
  if(flashAt>0){
    const k=(now-flashAt)/900;
    if(k<1){
      ctx.strokeStyle='rgba(98,231,155,'+(0.5*(1-k)).toFixed(3)+')';
      ctx.lineWidth=3;
      ctx.beginPath();ctx.arc(cx(exitC.c),cy(exitC.r),8+k*72,0,Math.PI*2);ctx.stroke();
    }
  }
  const p=allDone?1:Math.min(1,Math.max(0,acc/tickMs));
  for(let i=0;i<bots.length;i++){
    const b=bots[i];
    let x=cx(b.prev.c)+(cx(b.pos.c)-cx(b.prev.c))*p;
    let y=cy(b.prev.r)+(cy(b.pos.r)-cy(b.prev.r))*p;
    let rad=5.5;
    if(b.finishTick!=null){
      const s=Math.min(1,(tickCount-b.finishTick)/6);
      const a=b.id/NBOTS*Math.PI*2;
      x+=Math.cos(a)*CELL*0.32*s;
      y+=Math.sin(a)*CELL*0.32*s;
      rad=4.6;
    }
    ctx.fillStyle=b.color;
    ctx.beginPath();ctx.arc(x,y,rad,0,Math.PI*2);ctx.fill();
    ctx.lineWidth=1.4;ctx.strokeStyle='rgba(7,10,14,.85)';ctx.stroke();
    if(b.finishTick!=null){
      ctx.fillStyle='rgba(255,255,255,.95)';
      ctx.beginPath();ctx.arc(x,y,1.7,0,Math.PI*2);ctx.fill();
    }
  }
}

/* ---------------- hud ---------------- */
function updateHUD(now){
  let done=0;
  for(let i=0;i<bots.length;i++){
    const b=bots[i];
    if(b.finishTick!=null){
      done++;
      if(!fxSeen.has(b.id)){
        fxSeen.add(b.id);
        fx.push({x:cx(exitC.c),y:cy(exitC.r),start:now,big:false});
      }
    }
  }
  if(done!==lastDone){
    lastDone=done;
    completedEl.textContent=done+' / '+NBOTS;
    completedEl.classList.remove('bump');void completedEl.offsetWidth;completedEl.classList.add('bump');
    statDone.classList.toggle('done',done===NBOTS);
    if(done===NBOTS&&!flashDone){
      flashDone=true;flashAt=now;
      fx.push({x:cx(exitC.c),y:cy(exitC.r),start:now,big:true});
    }
  }
  const e=game.elapsed;
  timerEl.textContent='T+'+String(e).padStart(5,'0');
  timerSub.textContent=(e/tps).toFixed(1)+' s @ '+tps+' ticks/s';
  statusEl.textContent=allDone?'COMPLETE — FROZEN':(running?'EXPLORING…':'PAUSED');
  statusEl.classList.toggle('ok',allDone);
  seedEl.textContent='SEED '+seed;
}

/* ---------------- controls ---------------- */
$('#reset').addEventListener('click',function(){game.reset();this.blur();});
pauseBtn.addEventListener('click',function(){togglePause();this.blur();});
function togglePause(){
  running=!running;
  pauseBtn.textContent=running?'Pause':'Resume';
  if(running)lastFrame=performance.now();
}
speedInput.addEventListener('input',()=>{
  tps=+speedInput.value;tickMs=1000/tps;
  speedVal.textContent=tps+' t/s';
});
window.addEventListener('keydown',e=>{
  if(e.code!=='Space')return;
  const t=e.target.tagName;
  if(t==='BUTTON'||t==='INPUT'||t==='TEXTAREA')return;
  e.preventDefault();togglePause();
});

/* ---------------- main loop ---------------- */
function frame(now){
  requestAnimationFrame(frame);
  let dt=now-lastFrame;lastFrame=now;
  if(dt>100)dt=100;
  if(running&&!allDone){
    acc+=dt;let n=0;
    while(acc>=tickMs&&n<16&&!allDone){game.tick(1);acc-=tickMs;n++;}
    if(acc>tickMs)acc=tickMs;
  }
  draw(now);
  updateHUD(now);
}

/* ---------------- boot ---------------- */
init((Math.random()*4294967296)>>>0);
requestAnimationFrame(frame);
})();
</script>
</body>
</html>
